[CmdletBinding()]
param([string]$SkillRoot = (Join-Path (Get-Location) '.agents/skills/es-game-core-loop-validation'))
$ErrorActionPreference='Stop';$tmp=Join-Path $SkillRoot '.tmp-gate';New-Item -ItemType Directory -Force $tmp|Out-Null
try{$j=@{decision='partial';runtimeStatus='runtime-not-run'}|ConvertTo-Json;$c=@{status='passed';receiptCount=6}|ConvertTo-Json;$a=@{status='passed'}|ConvertTo-Json;$s=@{status='passed'}|ConvertTo-Json;$jp=Join-Path $tmp 'j.json';$cp=Join-Path $tmp 'c.json';$ap=Join-Path $tmp 'a.json';$sp=Join-Path $tmp 's.json';[IO.File]::WriteAllText($jp,$j);[IO.File]::WriteAllText($cp,$c);[IO.File]::WriteAllText($ap,$a);[IO.File]::WriteAllText($sp,$s);$r=& (Join-Path $SkillRoot 'scripts/Invoke-ESGameCoreLoopFinalGate.ps1') -EvidenceJoinPath $jp -CapabilityPath $cp -AdversarialPath $ap -StrictReceiptPath $sp|ConvertFrom-Json;if($r.decision -ne 'partial' -or $r.authority -ne 'ABCD-final-decision'){throw 'FINAL_GATE_RUNTIME_CAP_FAILED'};[ordered]@{status='passed';decision=$r.decision;runtimeStatus=$r.runtimeStatus;claimCapEnforced=$true}|ConvertTo-Json}finally{Remove-Item -LiteralPath $tmp -Recurse -Force -ErrorAction SilentlyContinue}
